/** Per-event shape table (Rust type strings) for runtime validation. */
export interface FieldShape {
  /** Field name as it appears in the decoded event (snake_case). */
  name: string;
  /** Contract type, verbatim from the source (e.g. `u64`, `Address`, `Option<Address>`). */
  type: string;
}

export interface EventShape {
  struct: string;
  eventKey: ContractEventName;
  fingerprint: string;
  /** Positional topic fields after the event-name symbol. */
  topics: FieldShape[];
  /** Symbol-keyed data fields. Additive-only: extra keys are allowed. */
  data: FieldShape[];
}

